function inlineFormat(text) {
  text = text.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  text = text.replace(/__(.+?)__/g, '<strong>$1</strong>');
  text = text.replace(/\*(.+?)\*/g, '<em>$1</em>');
  text = text.replace(/_(.+?)_/g, '<em>$1</em>');
  let result = '';
  let i = 0;
  while (i < text.length) {
    const bracketStart = text.indexOf('[', i);
    if (bracketStart === -1) { result += text.slice(i); break; }
    const bracketEnd = text.indexOf('](', bracketStart);
    if (bracketEnd === -1) { result += text.slice(i); break; }
    const linkText = text.slice(bracketStart + 1, bracketEnd);
    let depth = 1;
    let j = bracketEnd + 2;
    while (j < text.length && depth > 0) {
      if (text[j] === '(') depth++;
      else if (text[j] === ')') depth--;
      j++;
    }
    if (depth !== 0) { result += text.slice(i, bracketEnd + 1); i = bracketEnd + 1; continue; }
    const url = text.slice(bracketEnd + 2, j - 1);
    result += text.slice(i, bracketStart);
    result += '<a href="' + url + '">' + linkText + '</a>';
